link_text:
$(document).ready( function( e ) {

					$('#daterangepicker').dateRangePicker({
						format: 'DD-MM-YYYY',
						separator: ' - ',
						endDate: moment(),
						timePicker: false,
						applyClass: 'apply-btn',
					});

					$('.apply-btn').on('click', function(e) {
						$('#daterangepicker').trigger('change');
					});
				});
